    private void ToggleFormLogin()
    {
        isFormVisible = !isFormVisible;
    }
    private Services services = new Services();
    private UserLoginRequest userloginrequest = new UserLoginRequest();
    private async Task Authenticate()
    {
        isLoading = true; // Start loading
        UserSession userAccount = new();
        try
        {

            if (!string.IsNullOrEmpty(data.UserNameSSO) && data.UserNameSSO == "admin")
            {
                // userAccount = await userAccountService.GetByUserName(data.UserNameSSO.ToLower());
                userAccount = await userAccountService.GetSSOAccountAdmin(data.UserNameSSO.ToLower());

            }
            else if (!string.IsNullOrEmpty(data.UserNameSSO))
            {
                userAccount = await userAccountService.GetSSOAccountUser(data.UserNameSSO.ToLower());
            }

            else
            {
                userAccount = await userAccountService.GetAccountUser(data.UserName.ToLower());

                if (userAccount == null || userAccount.Password != data.Password)
                {
                    alertMessage = "Tên đăng nhập hoặc mật khẩu không hợp lệ";
                    return;
                }

            }

            var userSession = new UserSession
                {
                    UserName = userAccount.UserName,
                    Password = userAccount.Password,
                    Role = userAccount.Role,
                    MaTruongBo = userAccount.MaTruongBo,
                    TaiKhoanKySo = userAccount.TaiKhoanKySo,
                    MaUser = userAccount.MaUser,
                    SessionId = Guid.NewGuid().ToString(),
                    NamHoc = PN_Sessions.NamHoc,
                };

            // await UserState.InitializeAsync(userSession);

            var customAuthStateProvider = (CustomAuthenticationStateProvider)authStateProvider;
            await customAuthStateProvider.UpdateAuthenticationState(userSession);

            // Navigate after setting the authentication state
            navManager.NavigateTo("/");
        }
        catch (Exception ex)
        {
            alertMessage = "Có lỗi xảy ra, vui lòng thử lại sau.";
            Console.WriteLine(ex.Message); // Log the error for debugging
        }
        finally
        {
            isLoading = false; // End loading
        }
    }
    private async Task DirectToSSO(int role)
    {
        string currentUrl = navManager.Uri;
        int roleId = (role == 1) ? 1 : 2;
        ssoResponse = await httpContent.HandleDirectToSSO(roleId, currentUrl);
        await Services.hSaveSessionAsync(ssoResponse);
        navManager.NavigateTo(ssoResponse.Result);
    }
    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            var uri = navManager.ToAbsoluteUri(navManager.Uri);
            var query = Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query);

            if (query.ContainsKey("token"))
            {
                TokenProvider.AccessToken = query["token"];
                if (!string.IsNullOrEmpty(TokenProvider.AccessToken))
                {
                    await GetSessionAndLogin(TokenProvider.AccessToken);
                }
                else
                {
                    // Handle the case where the token is empty
                    Console.WriteLine("Token is empty");
                    return;

                    // You could also redirect the user to a login page or display an error message
                }
            }
            else
            {
                // Handle the case where the token is not present
                Console.WriteLine("Token is not present");
                return;
                // You could also redirect the user to a login page or display an error message
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions
            Console.WriteLine($"An error occurred: {ex.Message}");
            // You could also redirect the user to an error page or display an error message
        }
        finally
        {
            isLoading = false;
        }
    }
    //Function to execute SessionApi and check username of user
    private async Task GetSessionAndLogin(string token)
    {
        try
        {
            //get api getSesssion and save data to server
            ApiResponseSingle<ThongTinTruongSSO> responseData = new();
            var url = @"https://apigateway.hcm.edu.vn/SSO/CSDLAuth/getSessionData";
            //create request with params
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            //add Header
            request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("text/plain"));
            request.Headers.Add("Token", token.ToString());

            var response = await httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var responseContent = await response.Content.ReadAsStringAsync();
            responseData = JsonSerializer.Deserialize<ApiResponseSingle<ThongTinTruongSSO>>(responseContent, new JsonSerializerOptions
                {
                    PropertyNameCaseInsensitive = true
                });
            if (responseData != null && responseData.Result != null)
            {
                thongtin = responseData.Result;
                //Get the username of session currently and account
                data.UserNameSSO = thongtin.UserName.ToLower();
                await Authenticate();

            }
            // await SSO_Service.S (thongtin, "getThongTinTruong");
            // var accountData = JsonConvert.DeserializeObject
        }
        catch (Exception ex)
        {

            throw new ApplicationException(ex.ToString());
        }
    }
